import itertools

def solve_for_n(n):
    min_max_abs_sum = float('inf')
    for a in itertools.product([1, -1], repeat=n):
        max_abs_sum = 0
        # We need to find all subsets S = {t_1, ..., t_k} such that t_{i+1} - t_i <= 2
        # We can iterate through all subsets and check the condition
        for r in range(1, n + 1):
            for subset in itertools.combinations(range(n), r):
                # subset is already sorted
                valid = True
                for i in range(len(subset) - 1):
                    if subset[i+1] - subset[i] > 2:
                        valid = False
                        break
                if valid:
                    current_sum = sum(a[i] for i in subset)
                    max_abs_sum = max(max_abs_sum, abs(current_sum))
        min_max_abs_sum = min(min_max_abs_sum, max_abs_sum)
    return min_max_abs_sum

for n in range(1, 11):
    print(f"n={n}, C={solve_for_n(n)}")

import itertools

def get_max_abs_sum(a):
    n = len(a)
    dp_max = [-float('inf')] * n
    dp_min = [float('inf')] * n
    for i in range(n):
        dp_max[i] = max(dp_max[i], a[i])
        dp_min[i] = min(dp_min[i], a[i])
        if i >= 1:
            dp_max[i] = max(dp_max[i], dp_max[i-1] + a[i])
            dp_min[i] = min(dp_min[i], dp_min[i-1] + a[i])
        if i >= 2:
            dp_max[i] = max(dp_max[i], dp_max[i-2] + a[i])
            dp_min[i] = min(dp_min[i], dp_min[i-2] + a[i])
    return max(max(dp_max), -min(dp_min))

def solve_for_n_fast_all(n):
    min_max_abs_sum = float('inf')
    for a in itertools.product([1, -1], repeat=n):
        min_max_abs_sum = min(min_max_abs_sum, get_max_abs_sum(a))
    return min_max_abs_sum

results = {n: solve_for_n_fast_all(n) for n in range(1, 16)}
print(results)
